import{_ as t,H as e,f as s,i as n}from"./chunks/framework.nyB-Xt5O.js";const b=JSON.parse('{"title":"统计学快速复习","description":"","frontmatter":{},"headers":[],"relativePath":"learning-paths/path-1-basics/03-statistics.md","filePath":"learning-paths/path-1-basics/03-statistics.md","lastUpdated":1779798726000}'),i={name:"learning-paths/path-1-basics/03-statistics.md"};function l(r,a,d,o,h,p){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="统计学快速复习" tabindex="-1">统计学快速复习 <a class="header-anchor" href="#统计学快速复习" aria-label="Permalink to &quot;统计学快速复习&quot;">​</a></h1><blockquote><p>描述统计、推断统计、相关分析的快速回顾。深入参考请见 <a href="/data-analysis-learning/knowledge-map/km-3-statistics">KM 3. 统计学与概率论</a>。</p></blockquote><h2 id="描述性统计" tabindex="-1">描述性统计 <a class="header-anchor" href="#描述性统计" aria-label="Permalink to &quot;描述性统计&quot;">​</a></h2><h3 id="集中趋势" tabindex="-1">集中趋势 <a class="header-anchor" href="#集中趋势" aria-label="Permalink to &quot;集中趋势&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>适用场景</th><th>注意</th></tr></thead><tbody><tr><td>均值 (Mean)</td><td>数据对称分布</td><td>受异常值影响大</td></tr><tr><td>中位数 (Median)</td><td>偏态分布</td><td>对异常值鲁棒</td></tr><tr><td>众数 (Mode)</td><td>分类数据</td><td>—</td></tr></tbody></table><h3 id="离散程度" tabindex="-1">离散程度 <a class="header-anchor" href="#离散程度" aria-label="Permalink to &quot;离散程度&quot;">​</a></h3><ul><li><strong>方差 / 标准差</strong>：数据分散程度</li><li><strong>IQR（四分位距）</strong>：Q3 - Q1，用于箱线图</li><li><strong>CV（变异系数）</strong>：标准差 / 均值，比较不同量纲的离散程度</li></ul><h2 id="概率基础" tabindex="-1">概率基础 <a class="header-anchor" href="#概率基础" aria-label="Permalink to &quot;概率基础&quot;">​</a></h2><p><strong>贝叶斯定理</strong>：<code>P(A|B) = P(B|A) * P(A) / P(B)</code></p><p><strong>常见分布</strong>：</p><ul><li>正态分布：自然现象、测量误差</li><li>二项分布：n 次独立实验中成功 k 次</li><li>泊松分布：单位时间内事件发生次数</li></ul><h2 id="推断统计" tabindex="-1">推断统计 <a class="header-anchor" href="#推断统计" aria-label="Permalink to &quot;推断统计&quot;">​</a></h2><h3 id="中心极限定理" tabindex="-1">中心极限定理 <a class="header-anchor" href="#中心极限定理" aria-label="Permalink to &quot;中心极限定理&quot;">​</a></h3><p>无论总体分布如何，样本均值的分布趋近正态。这是大部分统计推断的理论基础。</p><h3 id="假设检验流程" tabindex="-1">假设检验流程 <a class="header-anchor" href="#假设检验流程" aria-label="Permalink to &quot;假设检验流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 设定 H0（零假设）和 H1（备择假设）</span></span>
<span class="line"><span>2. 选择显著性水平 α（通常 0.05）</span></span>
<span class="line"><span>3. 选择检验方法（t 检验 / 卡方 / ANOVA）</span></span>
<span class="line"><span>4. 计算 p-value</span></span>
<span class="line"><span>5. 若 p &lt; α，拒绝 H0</span></span></code></pre></div><h3 id="常见检验方法" tabindex="-1">常见检验方法 <a class="header-anchor" href="#常见检验方法" aria-label="Permalink to &quot;常见检验方法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检验</th><th>用途</th></tr></thead><tbody><tr><td>t 检验</td><td>两组均值对比</td></tr><tr><td>卡方检验</td><td>分类变量独立性</td></tr><tr><td>ANOVA</td><td>三组及以上均值对比</td></tr></tbody></table><h2 id="相关分析" tabindex="-1">相关分析 <a class="header-anchor" href="#相关分析" aria-label="Permalink to &quot;相关分析&quot;">​</a></h2><ul><li><strong>Pearson</strong>：线性相关（连续变量，正态分布）</li><li><strong>Spearman</strong>：单调相关（不要求正态）</li><li>相关 ≠ 因果：可能存在混淆变量</li></ul><blockquote><p>深入了解请参阅 <a href="/data-analysis-learning/knowledge-map/km-3-statistics">KM 3. 统计学与概率论</a>。</p></blockquote>`,21)])])}const u=t(i,[["render",l]]);export{b as __pageData,u as default};
